<?php
/**
 * Sitewide WhatsApp bubble (bottom-right) + AI chat launcher (bottom-left).
 * Single source: includes/contact-widgets.html (edge copy: data/contact-widgets.json,
 * regenerated by static-export). Injected into every exported HTML page.
 */
function icomplyContactWidgetsHtml(): string
{
    static $html = null;
    if ($html === null) {
        $html = (string)file_get_contents(__DIR__ . '/contact-widgets.html');
    }
    return $html;
}

function icomplyInjectContactWidgets(string $html): string
{
    if (str_contains($html, '<!--icomply-widgets-->') || stripos($html, '<html') === false) {
        return $html;
    }
    $w = icomplyContactWidgetsHtml();
    // Pages that already carry the legacy .wa-float bubble keep it; skip the duplicate.
    if (str_contains($html, 'class="wa-float"')) {
        $w = preg_replace('#<a class="icw-wa".*?</a>\n#s', '', $w) ?? $w;
    }
    $pos = strripos($html, '</body>');
    return $pos === false ? $html . $w : substr($html, 0, $pos) . $w . substr($html, $pos);
}

/** Post-process every HTML file in dist. Returns [pages, injected]. */
function icomplyInjectContactWidgetsDist(string $dist): array
{
    $pages = 0;
    $inj = 0;
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dist, FilesystemIterator::SKIP_DOTS));
    foreach ($it as $f) {
        $p = $f->getPathname();
        if (!preg_match('/\.(html|php)$/', $p) || str_contains($p, '/assets/')) {
            continue;
        }
        $html = (string)file_get_contents($p);
        if (stripos($html, '<html') === false) {
            continue;
        }
        $pages++;
        $new = icomplyInjectContactWidgets($html);
        if ($new !== $html) {
            file_put_contents($p, $new);
            $inj++;
        }
    }
    return [$pages, $inj];
}
